DELETE FROM program_credit_requirements WHERE program_id IN ('bus-mgt', 'bus-fin', 'bus-mkt', 'bus-adpr', 'bus-tour', 'bus-hrm', 'bus-ib', 'bus-sbm', 'bus-acc', 'bus-accfin');

-- Which courses belong to which major, and as what.
DELETE FROM program_courses WHERE program_id IN ('bus-mgt', 'bus-fin', 'bus-mkt', 'bus-adpr', 'bus-tour', 'bus-hrm', 'bus-ib', 'bus-sbm', 'bus-acc', 'bus-accfin');

-- Codes that are in no major any more AND have no name: they came from the earlier reading and
-- appear in no university document. Removed, unless something a student made refers to one.
DELETE FROM courses
WHERE (name_th IS NULL OR name_th = '')
  AND code NOT IN (SELECT course_code FROM program_courses)
  AND code NOT IN (SELECT course_code FROM chapter_mastery WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM chapters WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM class_sessions WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM course_lectures WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM enrollments WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM etesting_courses WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM exams WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM lecture_transcripts WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM materials WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM mock_exams WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM notes WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM plan_items WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM prerequisites WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT requires_code FROM prerequisites WHERE requires_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM questions WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM reminders WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM study_sessions WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM study_tasks WHERE course_code IS NOT NULL)
  AND code NOT IN (SELECT course_code FROM topics WHERE course_code IS NOT NULL);

-- The catalogue has gained courses, so the timetable and exams of every term on record are
-- rebuilt: the new courses get the class times and exam dates the registrar published.
DELETE FROM class_sessions WHERE term_id IN (SELECT DISTINCT term_id FROM term_offerings);
DELETE FROM exams WHERE term_id IN (SELECT DISTINCT term_id FROM term_offerings);
SELECT o.course_code, o.term_id, json_extract(s.value, '$.weekday'), json_extract(s.value, '$.start'), json_extract(s.value, '$.end'),
       NULLIF(json_extract(s.value, '$.room'), ''), o.teachers, NULLIF(json_extract(s.value, '$.kind'), '')
FROM term_offerings o, json_each(o.sessions) s
WHERE o.term_id IN (SELECT DISTINCT term_id FROM term_offerings) AND json_extract(s.value, '$.weekday') IS NOT NULL AND o.course_code IN (SELECT code FROM courses)
ORDER BY o.term_id, o.course_code, s.key;
SELECT course_code, term_id,
       exam_date || CASE exam_slot WHEN 'A' THEN 'T09:30:00+07:00' ELSE 'T14:00:00+07:00' END,
       exam_date || CASE exam_slot WHEN 'A' THEN 'T12:00:00+07:00' ELSE 'T16:30:00+07:00' END,
       exam_slot, NULL
FROM term_offerings
WHERE term_id IN (SELECT DISTINCT term_id FROM term_offerings) AND exam_date IS NOT NULL AND course_code IN (SELECT code FROM courses)
ORDER BY term_id, course_code;
